using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using Newtonsoft.Json.Linq;
public static class OperationalRefresh {
 const string P="Assets/Afrer_Seconds/05.Model/Props/B5/",E="Assets/Afrer_Seconds/05.Model/Environment/B5/";static string Repo=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty)throw new Exception("Saved Edit required");string texpath=P+"Textures/OD_Screen_Stock.png";AssetDatabase.ImportAsset(texpath,ImportAssetOptions.ForceSynchronousImport);var ti=(TextureImporter)AssetImporter.GetAtPath(texpath);ti.maxTextureSize=1024;ti.mipmapEnabled=true;ti.textureCompression=TextureImporterCompression.CompressedHQ;ti.SaveAndReimport();var m=AssetDatabase.LoadAssetAtPath<Material>(P+"Materials/OD_Screen_Stock.mat");if(!m){m=new Material(AssetDatabase.LoadAssetAtPath<Material>(P+"Materials/OD_Screen_Food.mat"));AssetDatabase.CreateAsset(m,P+"Materials/OD_Screen_Stock.mat");}var tex=AssetDatabase.LoadAssetAtPath<Texture2D>(texpath);m.name="OD_Screen_Stock";m.SetTexture("_BaseMap",tex);m.SetTexture("_EmissionMap",tex);EditorUtility.SetDirty(m);AssetDatabase.SaveAssetIfDirty(m);
 var manifest=JObject.Parse(File.ReadAllText(Repo+"/SourceAssets/B5_OperationalDetail/models.json"));foreach(var q in manifest){string path=((string)q.Value["category"]=="Environment"?E:P)+q.Key+".fbx";AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceUpdate|ImportAssetOptions.ForceSynchronousImport);var mi=(ModelImporter)AssetImporter.GetAtPath(path);foreach(var mat in AssetDatabase.LoadAssetAtPath<GameObject>(path).GetComponentsInChildren<Renderer>().SelectMany(r=>r.sharedMaterials).Where(x=>x).Distinct()){string n=mat.name;var target=AssetDatabase.LoadAssetAtPath<Material>(P+"Materials/"+n+".mat");if(n.StartsWith("RD_")){var sf=AssetDatabase.LoadAssetAtPath<Material>(P+"Materials/SF_"+n.Substring(3)+".mat");if(sf)target=sf;}if(!target)throw new Exception("Material missing "+n);mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),n),target);}mi.SaveAndReimport();}
 var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform.Find("B5_Operational_Detail");foreach(var f in root.GetComponentsInChildren<MeshFilter>()){var mc=f.GetComponent<MeshCollider>();if(mc)mc.sharedMesh=f.sharedMesh;PrefabUtility.RecordPrefabInstancePropertyModifications(f.transform);foreach(var r in f.GetComponents<Renderer>())PrefabUtility.RecordPrefabInstancePropertyModifications(r);}Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{models=manifest.Count};}
}
